<?php
require_once __DIR__ . '/includes/layout.php'; require_once __DIR__ . '/config/database.php'; checkRole(['RESPONSAVEL']); $db=getDB();$escolinha=currentEscolinhaId();
$q=$db->prepare('SELECT COD_RESPONSAVEL FROM TB_RESPONSAVEL WHERE COD_USUARIO=? AND COD_ESCOLINHA=?');$q->execute([$_SESSION['user_id'],$escolinha]);$responsavel=(int)$q->fetchColumn();
$q=$db->prepare("SELECT a.*, GROUP_CONCAT(DISTINCT t.NOME SEPARATOR ', ') AS TURMAS, ROUND(AVG(p.PRESENTE)*100,1) AS FREQUENCIA FROM TB_ALUNO a LEFT JOIN TB_MATRICULA m ON m.COD_ALUNO=a.COD_ALUNO AND m.STATUS='ATIVA' LEFT JOIN TB_TURMA t ON t.COD_TURMA=m.COD_TURMA LEFT JOIN TB_PRESENCA p ON p.COD_ALUNO=a.COD_ALUNO WHERE a.COD_RESPONSAVEL=? AND a.COD_ESCOLINHA=? GROUP BY a.COD_ALUNO ORDER BY a.NOME");$q->execute([$responsavel,$escolinha]);$alunos=$q->fetchAll();pageStart('Meus alunos');
?><?php if(!$responsavel):?><div class="rounded-lg border border-amber-200 bg-amber-50 p-4 text-amber-900">Seu usuário ainda não está associado a um responsável. Solicite esse vínculo à secretaria.</div><?php else:?><div class="grid gap-5 md:grid-cols-2"><?php foreach($alunos as $a):?><article class="rounded-xl border bg-white p-5 shadow-sm"><h2 class="text-lg font-bold text-emerald-950"><?=e($a['NOME'])?></h2><dl class="mt-3 space-y-2 text-sm"><div><dt class="font-medium text-slate-500">Situação</dt><dd><?=e($a['STATUS'])?></dd></div><div><dt class="font-medium text-slate-500">Turma(s)</dt><dd><?=e($a['TURMAS']?:'Sem matrícula ativa')?></dd></div><div><dt class="font-medium text-slate-500">Frequência</dt><dd><?=$a['FREQUENCIA']===null?'Ainda sem chamadas':e($a['FREQUENCIA']).'%'?></dd></div><div><dt class="font-medium text-slate-500">Observações médicas</dt><dd><?=e($a['OBSERVACOES_MEDICAS']?:'Nenhuma registrada')?></dd></div></dl></article><?php endforeach;?></div><?php if(!$alunos):?><p class="text-slate-500">Nenhum aluno associado a este responsável.</p><?php endif;?><?php endif;?><?php pageEnd();?>
